import{_ as t,c as a,o as i,ah as o,aj as r}from"./chunks/framework.CJBcqVjN.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"title":"FAQ"},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),n={name:"faq.md"};function s(l,e,d,h,p,c){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h1><h3 id="_1-is-it-possible-to-download-the-challenge-dataset-without-participating-in-the-challenge" tabindex="-1">1. Is it possible to download the challenge dataset without participating in the challenge? <a class="header-anchor" href="#_1-is-it-possible-to-download-the-challenge-dataset-without-participating-in-the-challenge" aria-label="Permalink to “1. Is it possible to download the challenge dataset without participating in the challenge?”">​</a></h3><p>Yes, under controlled access, with additional restrictions to ensure the fairness of the MICCAI challenge.</p><p>To prevent potential leakage of paired data to participating teams and to preserve the integrity and fairness of the challenge evaluation, priority is given to the MICCAI challenge process. Therefore:</p><ul><li>Access requests from non-participating researchers will only be considered after the official release of the challenge results.</li></ul><p>Researchers who do not intend to participate in the challenge but wish to use the dataset must submit a research proposal to the <strong>MRIxFields Consortium</strong> (<a href="mailto:mrixfields@outlook.com" target="_blank" rel="noreferrer">mrixfields@outlook.com</a>) for review. Access will be granted only upon approval by the Consortium.</p><p>All approved users are required to comply with the data usage agreement. In particular:</p><ul><li>Results derived from the dataset may only be published no earlier than <strong>three months after the official end of the challenge</strong></li><li>The <strong>challenge paper</strong> must be properly cited</li><li>The <strong>dataset source</strong> must be explicitly acknowledged in any publication</li></ul><p>In addition, prior to manuscript submission, users must notify the <strong>MRIxFields Consortium</strong> (<a href="mailto:mrixfields@outlook.com" target="_blank" rel="noreferrer">mrixfields@outlook.com</a>), providing:</p><ul><li>A description of how the dataset was used in the study</li><li>A copy of the manuscript intended for submission</li></ul><p>Furthermore, all resulting publications must include <strong>“MRIxFields Consortium”</strong> as a group author in the author list, typically listed at the end of the author list.</p><p>For the full consortium author list, please download the document <a href="./consortium_list.docx" download>here</a>.</p><h3 id="_2-can-other-datasets-or-pre-trained-models-be-used-to-develop-the-reconstruction-algorithms" tabindex="-1">2. Can other datasets or pre-trained models be used to develop the reconstruction algorithms? <a class="header-anchor" href="#_2-can-other-datasets-or-pre-trained-models-be-used-to-develop-the-reconstruction-algorithms" aria-label="Permalink to “2. Can other datasets or pre-trained models be used to develop the reconstruction algorithms?”">​</a></h3><p>Yes. Any publicly available datasets may be used for training. However, participants are not allowed to use their own private data in order to ensure the fairness of this challenge. Data augmentation based on the training dataset is allowed.</p><h3 id="_3-what-is-the-maximum-number-of-team-members-allowed" tabindex="-1">3. What is the maximum number of team members allowed? <a class="header-anchor" href="#_3-what-is-the-maximum-number-of-team-members-allowed" aria-label="Permalink to “3. What is the maximum number of team members allowed?”">​</a></h3><p>Each team can consist of up to <strong>6 people</strong>.</p><h3 id="_4-can-we-preprocess-the-data" tabindex="-1">4. Can we preprocess the data? <a class="header-anchor" href="#_4-can-we-preprocess-the-data" aria-label="Permalink to “4. Can we preprocess the data?”">​</a></h3><p>We do not restrict data preprocessing, and we only evaluate the final generation performance. However, the total running time for all data in each task cannot exceed <strong>1 hour</strong>.</p><h3 id="_5-do-we-need-to-upload-the-training-code" tabindex="-1">5. Do we need to upload the training code? <a class="header-anchor" href="#_5-do-we-need-to-upload-the-training-code" aria-label="Permalink to “5. Do we need to upload the training code?”">​</a></h3><p>We do not require teams to upload the training code. Only the <strong>Docker image for the inference code</strong> is required for participation.</p><h3 id="_6-does-the-validation-submission-affect-the-final-ranking" tabindex="-1">6. Does the validation submission affect the final ranking? <a class="header-anchor" href="#_6-does-the-validation-submission-affect-the-final-ranking" aria-label="Permalink to “6. Does the validation submission affect the final ranking?”">​</a></h3><p>No, the validation submission does <strong>not</strong> affect the final ranking.</p><h3 id="_7-how-many-submissions-are-allowed" tabindex="-1">7. How many submissions are allowed? <a class="header-anchor" href="#_7-how-many-submissions-are-allowed" aria-label="Permalink to “7. How many submissions are allowed?”">​</a></h3><p>During the validation phase, each team is allowed to submit up to three times per day per task. In the test phase, each team can submit up to five Docker containers per task in total. The final ranking will be based on the results of the last submission.</p><h3 id="_8-can-we-participate-in-only-one-task" tabindex="-1">8. Can we participate in only one task? <a class="header-anchor" href="#_8-can-we-participate-in-only-one-task" aria-label="Permalink to “8. Can we participate in only one task?”">​</a></h3><p>Yes, participants are free to join any single task. Of course, they are also welcome to participate in multiple or all tasks. Each task will be evaluated, ranked, and awarded independently.</p><h1 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to “Rules”">​</a></h1><ol><li><p>All individuals who wish to participate in this challenge are required to register using their real name, affiliation details (including department, university/institute/company name in full, country), and affiliation emails. Incomplete and repetitive registrations will be removed without prior notice. Each team is permitted to have a maximum of six members.</p></li><li><p>During the validation and training phase, all participants must submit a complete solution to this challenge, which includes a Docker image and a qualified methodology paper (of at least 8 pages, in LNCS format). If you are downloading the data for purposes other than participating in the challenge, please refer to our explanation in the FAQ.</p></li><li><p>All participants must agree that their methodology can be made publicly available on the challenge website, and that organizers can use information provided by participants, including scores, predicted labels, and papers.</p></li><li><p>Participants are not allowed to register multiple teams or accounts. The MRIxFields Organizers reserve the right to disqualify such participants.</p></li><li><p>Redistribution or transfer of data or data links is prohibited. Participants must use the data solely for their own purposes.</p></li><li><p>Any publicly available datasets can be used for training. However, participants are not allowed to use their own private data to ensure the fairness of this challenge. Data augmentation based on the training dataset is allowed. No manual interventions, such as manual annotation of cases, are allowed.</p></li><li><p>For Task 1 and Task 2, participants may design separate models for different input field strengths (4 input field strengths) and different image contrasts (T1w, T2w, T2-FLAIR) to address field-dependent variations in noise, resolution, and contrast behavior. That is, you may provide 12 separate models for image generation. However, for Task 3, participants must utilize a single unified conditional model to enable dynamic image generation conditioned on desired target field parameters. You may use a prompt-based mechanism, but only one set of pretrained parameters is allowed to be stored for Task 3. If a participating team submits multiple models for Task 3, the submission will be disqualified and no score will be counted.</p></li><li><p>Participants may choose to use a single contrast (e.g., T1w) as input for model inference, or multiple contrasts (e.g., T1w + T2w + T2-FLAIR). The outputs can be either multi-contrast or single-contrast. We do not impose any restrictions on how participants use the provided data. However, please note that in the retrospective dataset, not every case includes all contrasts (T1w + T2w + T2-FLAIR). For matching across contrasts, please refer to the following: for each individual NIfTI file, our naming convention is &quot;field strength_ID&quot;, for example, &quot;5T_002&quot;. Please note that the same ID corresponds to the same subject, while different IDs correspond to different subjects. Therefore, if you intend to use multi-contrast data for training, you will need to match the IDs accordingly. For retrospective data (from different subjects), we only performed rigid registration. If you are not satisfied with the cross-contrast alignment, you may perform your own registration. For prospective data (from the same subject), we applied deformable registration to achieve better spatial consistency across field strengths and contrasts.</p></li><li><p>During the validation phase, to ensure efficiency in image segmentation, participants are required to perform segmentation locally and upload the segmentation results along with their submissions to the validation platform. During the test phase, participants only need to submit their inference Docker container, and we will perform standardized segmentation and evaluation.</p></li><li><p>During the validation phase, each team is allowed to submit up to three times per day per task. In the test phase, each team can submit up to five Docker containers per task in total. The final ranking will be based on the results of the last submission.</p></li><li><p>For each task, during both the validation and test phases, you are required to generate the corresponding target field-strength images for all provided cases and all contrasts. Missing results will lead to the lowest possible score for that metric, which will in turn affect the overall score.</p></li><li><p>Detailed examples of the required output file structure will be provided on our GitHub: <a href="https://github.com/mrixfields" target="_blank" rel="noreferrer">https://github.com/mrixfields</a> .</p></li></ol><div style="margin:24px 0;"><img src="'+r+'" alt="Consortium logos" style="display:block;max-width:60%;height:auto;margin:0 auto;"></div>',29)])])}const f=t(n,[["render",s]]);export{m as __pageData,f as default};
